import * as THREE from './vendor/three.module.js';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import {normalizeAppearance,paintColor,STRIPES,GLOWS} from './customization.js';
import {STRIPE_VERTICES} from './car-stripes.js';
import {MODEL_STRIPES} from './car-model-stripes.js';
import {carModel} from './car-models.js';
import {RoomEnvironment} from './vendor/RoomEnvironment.js';
import {fitCarPreview} from './car-preview-fit.js';
export function carEnvironment(renderer){const room=new RoomEnvironment(),pmrem=new THREE.PMREMGenerator(renderer),target=pmrem.fromScene(room,.04);room.dispose();pmrem.dispose();return target;}
const sources=new Map(),pending=new Map(),paintTextures=new Map();
function loadSource(id,lod=false){const config=carModel(id),key=lod&&config.lod?id+'-lod':id;if(sources.has(key))return Promise.resolve(sources.get(key));if(pending.has(key))return pending.get(key);const task=new GLTFLoader().loadAsync(lod&&config.lod?config.lod:config.file).then(g=>{sources.set(key,g.scene);pending.delete(key);return g.scene;}).catch(e=>{pending.delete(key);throw e;});pending.set(key,task);return task;}
export async function loadCarModel(id='classic',{includeLod=false}={}){const root=await loadSource(id);if(includeLod&&carModel(id).lod)await loadSource(id,true);return root;}
function paintedTexture(original,color){if(paintTextures.has(color))return paintTextures.get(color);const canvas=document.createElement('canvas');canvas.width=canvas.height=512;const ctx=canvas.getContext('2d');ctx.drawImage(original.image,0,0,512,512);ctx.fillStyle=color;ctx.fillRect(256,0,256,512);ctx.fillRect(128,0,384,128);const texture=new THREE.CanvasTexture(canvas);texture.flipY=original.flipY;texture.colorSpace=THREE.SRGBColorSpace;texture.wrapS=original.wrapS;texture.wrapT=original.wrapT;texture.anisotropy=4;paintTextures.set(color,texture);return texture;}
export function disposeCar(root){const materials=new Set();root.traverse(o=>{if(o.isMesh){for(const m of Array.isArray(o.material)?o.material:[o.material])materials.add(m);if(o.userData.cosmetic)o.geometry.dispose();}});materials.forEach(m=>{if(m.userData.ownedMap)m.map.dispose();m.dispose();});}
export function buildCar(spec,raw,colorOverride,{lod=false}={}){
 const imported=spec.id!=='classic',config=carModel(spec.id),source=sources.get(lod&&config.lod?spec.id+'-lod':spec.id);if(!source)throw Error('Car model not prepared: '+spec.id);
 const look=normalizeAppearance(raw),g=new THREE.Group(),root=source.clone(true),discard=[];
 root.traverse(o=>{if(o.isLight||o.isCamera||o.isMesh&&o.material.name==='Fabric')discard.push(o);});discard.forEach(o=>o.removeFromParent());
 root.rotation.y+=config.yaw;root.updateMatrixWorld(true);const box=new THREE.Box3().setFromObject(root,true),size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3());root.position.sub(new THREE.Vector3(center.x,box.min.y,center.z));const body=new THREE.Group();body.add(root);body.scale.setScalar(1.45/size.x);g.add(body);const length=size.z*1.45/size.x,height=size.y*1.45/size.x;
 root.traverse(o=>{if(!o.isMesh)return;o.material=o.material.clone();o.castShadow=true;o.receiveShadow=true;const m=o.material;if(m.name==='ToyCar'){m.map=paintedTexture(m.map,colorOverride||paintColor(spec,look));m.color.set('#ffffff');m.emissiveMap=null;m.emissive.set('#000000');m.roughness=look.finish==='matte'?.88:.26;m.metalness=look.finish==='matte'?.04:.22;m.clearcoat=look.finish==='matte'?0:.8;m.clearcoatRoughness=.18;}if(m.name==='Glass'){m.transmission=0;m.transparent=false;m.color.set('#283f49');m.roughness=.15;m.metalness=.3;}});
 if(imported){const hidden=[];root.traverse(o=>{if(!o.isMesh)return;const m=o.material,paint=m.userData.coastPaint;if(paint){m.color.set(colorOverride||paintColor(spec,look)).multiplyScalar(paint);m.roughness=look.finish==='matte'?.85:.24;m.metalness=look.finish==='matte'?.05:.45;m.clearcoat=look.finish==='matte'?0:1;}if(m.transmission>0||spec.id==='gt'&&m.name==='Material'||/glass|window/i.test(m.name)&&!/red|orange|lamp/i.test(m.name)){m.transmission=0;m.transparent=true;m.opacity=.82;m.color.set('#2f475a');m.roughness=.1;}if(m.userData.coastSpoiler&&look.spoiler!=='stock')hidden.push(o);});for(const o of hidden){o.material.dispose();o.removeFromParent();}}
 const addMesh=(geometry,material,x,y,z)=>{const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);m.userData.cosmetic=true;g.add(m);return m;};
 if(look.stripe!=='none'){
  const color=STRIPES.find(s=>s.id===look.stripe).color,geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(imported?MODEL_STRIPES[spec.id]||[]:STRIPE_VERTICES,3));geo.computeVertexNormals();addMesh(geo,new THREE.MeshStandardMaterial({color,roughness:.45,side:THREE.DoubleSide,polygonOffset:true,polygonOffsetFactor:-2}),0,0,0);
 }
 const wing=look.spoiler==='wing'||!imported&&look.spoiler==='stock'&&spec.style!=='classic';if(wing){const tall=look.spoiler==='wing',top=imported?height*.95:1.02,rear=imported?-length*.4:-1.25;addMesh(new THREE.BoxGeometry(1.55,.09,.3),new THREE.MeshStandardMaterial({color:'#20313d',roughness:.35}),0,top,rear);for(const x of [-.55,.55])addMesh(new THREE.BoxGeometry(.07,.3,.08),new THREE.MeshStandardMaterial({color:'#20313d'}),x,top-.15,rear);}
 if(look.glow!=='none'){const color=GLOWS.find(o=>o.id===look.glow).color,canvas=document.createElement('canvas');canvas.width=64;canvas.height=128;const ctx=canvas.getContext('2d');ctx.translate(32,64);ctx.scale(32,64);const grad=ctx.createRadialGradient(0,0,.05,0,0,1);grad.addColorStop(0,'white');grad.addColorStop(1,'transparent');ctx.fillStyle=grad;ctx.fillRect(-1,-1,2,2);const texture=new THREE.CanvasTexture(canvas),m=new THREE.MeshBasicMaterial({color,map:texture,transparent:true,opacity:.6,depthWrite:false,blending:THREE.AdditiveBlending,toneMapped:false});m.userData.ownedMap=true;const glow=addMesh(new THREE.PlaneGeometry(2.3,3.9),m,0,.025,0);glow.rotation.x=-Math.PI/2;}
 g.userData.model=spec.id;g.userData.length=length;return g;
}
export async function createCarPreview(canvas,spec,look){
 await loadCarModel(spec.id);const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;const scene=new THREE.Scene(),environment=carEnvironment(renderer),camera=new THREE.PerspectiveCamera(35,1,.1,30);scene.environment=environment.texture;scene.environmentIntensity=1.2;camera.position.set(3.2,2.0,4.3);camera.lookAt(0,.5,0);camera.updateProjectionMatrix();scene.add(new THREE.HemisphereLight('#d6eeff','#71818e',2.5));const light=new THREE.DirectionalLight('#fff3e0',3);light.position.set(2,5,3);scene.add(light);const fill=new THREE.DirectionalLight('#7ae7ff',2);fill.position.set(-3,2,-3);scene.add(fill);let car,alive=true,frame,needsFit=true;
 function update(next){if(car){scene.remove(car);disposeCar(car);}car=buildCar(spec,next);car.rotation.y=-.45;scene.add(car);needsFit=true;}
 update(look);function render(){if(!alive)return;const r=canvas.getBoundingClientRect(),w=Math.max(1,r.width),h=Math.max(1,r.height);if(canvas.width!==Math.round(w*renderer.getPixelRatio())||canvas.height!==Math.round(h*renderer.getPixelRatio())){renderer.setSize(w,h,false);needsFit=true;}if(needsFit){fitCarPreview(camera,car,w/h);needsFit=false;}renderer.render(scene,camera);frame=requestAnimationFrame(render);}render();return {update,snapshot(){renderer.render(scene,camera);const copy=document.createElement('canvas');copy.width=canvas.width;copy.height=canvas.height;const ctx=copy.getContext('2d');ctx.drawImage(canvas,0,0);const pixels=ctx.getImageData(0,0,copy.width,copy.height).data;let left=copy.width,right=-1,top=copy.height,bottom=-1;for(let y=0;y<copy.height;y++)for(let x=0;x<copy.width;x++)if(pixels[(y*copy.width+x)*4+3]>2){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}if(right<left)return copy.toDataURL('image/png');const width=right-left+1,height=bottom-top+1,pad=Math.ceil(Math.max(width,height)*.06),image=document.createElement('canvas');image.width=width+pad*2;image.height=height+pad*2;image.getContext('2d').drawImage(copy,left,top,width,height,pad,pad,width,height);return image.toDataURL('image/png');},dispose(){alive=false;cancelAnimationFrame(frame);scene.remove(car);disposeCar(car);environment.dispose();renderer.dispose();renderer.forceContextLoss();}};
}
